import java.util.*;
class TeachingMST { static class DS{int[] p;DS(int n){p=new int[n];for(int i=0;i<n;i++)p[i]=i;}int find(int x){return p[x]==x?x:(p[x]=find(p[x]));}void union(int a,int b){p[find(a)]=find(b);}} static class E implements Comparable<E>{int u,v,w;E(int u,int v,int w){this.u=u;this.v=v;this.w=w;}public int compareTo(E o){return w-o.w;}} static int kruskal(){DS ds=new DS(4);E[] e={new E(0,1,1),new E(1,2,2),new E(0,2,4),new E(2,3,3)};Arrays.sort(e);int total=0;for(E x:e)if(ds.find(x.u)!=ds.find(x.v)){ds.union(x.u,x.v);total+=x.w;System.out.println("take edge "+x.u+"-"+x.v);}return total;} }
